WITH with_windows AS (SELECT *, AVG(units) OVER (PARTITION BY YEAR(sale_date), product_id ORDER BY revenue ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS units_avg_3, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue DESC, id ASC) AS row_seq, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY units ASC, id ASC) AS event_seq, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('week', sale_date), product_id ORDER BY units DESC, id ASC) AS event_seq_2, DENSE_RANK() OVER (PARTITION BY product_id, store_id ORDER BY units DESC NULLS FIRST) AS units_dense_rank FROM store_sales) SELECT s.id, s.store_id, s.product_id, s.sale_date, s.revenue, s.row_seq, s.event_seq, (SELECT MAX(x.revenue) FROM store_sales x WHERE x.store_id = s.store_id) AS max_store_sale_revenue FROM with_windows s ORDER BY id ASC NULLS FIRST
